Here's a JavaScript code snippet that retrieves information from countries.json:

```javascript
const fs = require('fs');

// Function to read and process the JSON file
function readCountries() {
    // Read the JSON file
    fs.readFile('countries.json', 'utf8', (err, data) => {
        if (err) {
            console.error('Error reading the file:', err);
            return;
        }

        try {
            // Parse the JSON data
            const countries = JSON.parse(data);

            // Process the data (e.g., log each country's name and capital)
            countries.forEach(country => {
                console.log(`Country: ${country.name}, Capital: ${country.capital}, Population: ${country.population}`);
            });
        } catch (parseError) {
            console.error('Error parsing JSON:', parseError);
        }
    });
}

// Call the function to read and process the countries
readCountries();
```

