    val compiler = backend.Compiler()

    var scope: backend.Context? = null
    for (i in 0 until parseTree.childCount) {
        val child = parseTree.getChild(i)
        val stmt = compiler.visit(child)
        scope = backend.Context()
        stmt.eval(scope)
    }

    // Show the result
    println("Result: $scope")
}

