Here is an example implementation:

```kotlin
// Define the grammar for the programming language
grammar SimpleLang;

program: statement* EOF;

statement
    : varDeclaration
    ;

varDeclaration
    : 'int' ID '=' INT ';'
    | 'string' ID '=' STRING ';'
    ;

ID: [a-zA-Z_][a-zA-Z0-9_]*;
INT: [0-9]+;
STRING: '"' (~["])* '"';
WS: [ \t\r\n]+ -> skip;

// Create a visitor that compiles the parsed code into executable code
class SimpleLangVisitor(ParseTreeVisitor) {
    override fun visitVarDeclaration(ctx: VarDeclarationContext): Unit {
        val varName = ctx.ID().getText()
        if (ctx.INT() != null) {
            val value = int(ctx.INT().getText())
            // Define a variable in the context with the given name and value
