        }
    }

    override fun visitProgram(ctx: ProgramContext): Unit {
        for (statement in ctx.statement()) {
            visit(statement)
        }
    }
}

// Create a compiler that uses the visitor to compile the parsed code into executable code
class Compiler : PLBaseVisitor<Expr>() {
