            return IntegerExpression(value)
        } else if (ctx.STRING() != null) {
            val value = ctx.STRING().getText().strip('"')
            // Create a string expression with the given value
            return StringExpression(value)
        }
        throw RuntimeException("Unsupported variable declaration")
    }

    override fun visitProgram(ctx: ProgramContext): Expr {
        for (statement in ctx.statement()) {
            visit(statement)
        }
        // Return an empty expression as the compiled program
        return EmptyExpr()
    }
}

// Compile the evaluated expressions into executable code
class ExecutableCodeGenerator : Compiler() {
    override fun generateExecutableCode(expr: Expr): String {
