        scanner.close();
        System.out.println("Thank you for using Expense Splitter!");
    }

    private static void inputExpenses(Scanner scanner) {
        System.out.print("Enter the number of expenses: ");
        int numExpenses = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        for (int i = 0; i < numExpenses; i++) {
            System.out.print("Enter expense amount for category (restaurants/others): ");
            double amount = scanner.nextDouble();
            expenses.add(amount);
            scanner.nextLine(); // Consume newline
        }
        System.out.println("Expenses recorded.");
    }

    private static void setNumberOfFriends(Scanner scanner) {
        System.out.print("Enter the number of friends: ");
        numberOfFriends = scanner.nextInt();
        scanner.nextLine(); // Consume newline
        System.out.println("Number of friends set to " + numberOfFriends);
    }

    private static void addPlace(Scanner scanner) {
        System.out.print("Enter the name of the place: ");
        String place = scanner.nextLine();
        places.add(place);
        System.out.println("Place added: " + place);
    }

    private static void calculateAndSplit() {
        if (numberOfFriends <= 0) {
            System.out.println("Please set the number of friends first.");
            return;
        }

        double totalAmount = 0;
        for (double expense : expenses) {
            totalAmount += expense;
        }

        double amountPerFriend = totalAmount / numberOfFriends;
        System.out.printf("Total amount spent: %.2f\n", totalAmount);
        System.out.printf("Each friend should pay: %.2f\n", amountPerFriend);
        System.out.println("Places visited: " + places);
    }
}
```

### How to Run the Application

1. **Set Up Java Environment**: Ensure you have Java Development Kit (JDK) installed on your machine.

2. **Create a New Java File**: Copy the above code into a file named `ExpenseSplitter.java`.

3. **Compile the Application**: Open a terminal or command prompt, navigate to the directory where the file is located, and run:
   ```bash
   javac ExpenseSplitter.java
   ```

4. **Run the Application**: After compiling, run the application with:
   ```bash
   java ExpenseSplitter
   ```

### Features of the Application

- **Input Expenses**: Users can input multiple expenses categorized as restaurants or others.
- **Set Number of Friends**: Users can specify how many friends are sharing the expenses.
- **Add Places**: Users can add names of places where they incurred expenses.
- **Calculate and Split**: The application calculates the total expenses and divides it equally among the friends.
- **Exit Option**: Users can exit the application gracefully.

This application is a simple console-based implementation. You can enhance it further by adding features like data persistence, a graphical user interface (GUI), or more complex expense categorization.

