Next, create a new JavaScript file named `script.js` and add the following code:

```javascript
document.addEventListener('DOMContentLoaded', function() {
    const apiKeyInput = document.getElementById('api_key');
    const languageSelect = document.getElementById('language');
    const complexitySelect = document.getElementById('complexity');
    const versionInput = document.getElementById('version');
    const promptInput = document.getElementById('prompt');
    const generateButton = document.querySelector('.btn.btn-primary.btn-block');
    const codeOutput = document.getElementById('code-output');

    generateButton.addEventListener('click', generateProgram);

    function generateProgram() {
        const apiKey = apiKeyInput.value;
        const language = languageSelect.value;
        const complexity = complexitySelect.value;
        const version = versionInput.value;
        const prompt = promptInput.value;

        if (!apiKey || !prompt) {
            alert('Por favor, insira sua chave de API e prompt.');
            return;
        }

        // Simulação de chamada de API para gerar código
        generateCode(language, complexity, version, prompt).then(response => {
            const generatedCode = `Linguagem: ${language}\nComplexidade: ${complexity}\nVersão do ChatGPT: ${version}\nPrompt: ${prompt}\n\n// Seu código gerado estará aqui!\n\n${response.code}`;
            codeOutput.textContent = generatedCode;
        });
    }

    function generateCode(language, complexity, version, userInput) {
        // Simulate an API call with a delay
        return new Promise((resolve) => {
            setTimeout(() => {
                let generatedCode = '';

                // Generate code based on language and complexity
                switch (language.toLowerCase()) {
                    case 'javascript':
                        if (complexity === 'simple') {
                            generatedCode = `// Simple JavaScript code\nconsole.log('${userInput}');`;
                        } else if (complexity === 'complex') {
                            generatedCode = `// Complex JavaScript code\nfunction greet(name) {\n    return 'Hello, ' + name;\n}\nconsole.log(greet('${userInput}'));`;
                        }
                        break;

                    case 'python':
                        if (complexity === 'simple') {
                            generatedCode = `# Simple Python code\nprint('${userInput}')`;
                        } else if (complexity === 'complex') {
                            generatedCode = `# Complex Python code\ndef greet(name):\n    return 'Hello, ' + name\nprint(greet('${userInput}'))`;
                        }
                        break;

                    case 'java':
                        if (complexity === 'simple') {
                            generatedCode = `// Simple Java code\nSystem.out.println('${userInput}');`;
                        } else if (complexity === 'complex') {
                            generatedCode = `// Complex Java code\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(greet('${userInput}'));\n    }\n    public static String greet(String name) {\n        return "Hello, " + name;\n    }\n}`;
                        }
                        break;

                    default:
                        generatedCode = 'Unsupported language';
                }

                // Resolve the promise with the generated code
                resolve({
                    version: version,
                    code: generatedCode
                });
            }, 1000); // Simulate a 1 second delay for the API call
        });
    }
});
```

This updated JavaScript code integrates the provided function `generateCode` into your HTML form. When you click the "Gerar Código" button, it will simulate an API call and generate the corresponding code based on the selected language and complexity level.

