Here's an enhanced version of the todo list application that includes features like removing items, saving the list to a file, and marking items as completed.

### Enhanced Todo List Application

```go
package main

import (
	"fmt"
	"os"

	"github.com/therecipe/qt/gui"
	"github.com/therecipe/qt/widgets"
)

type TodoApp struct {
	*widgets.QWidget
	todoList  *widgets.QListWidget
	inputLine *widgets.QLineEdit
	addButton *widgets.QPushButton
	removeButton *widgets.QPushButton
	saveButton *widgets.QPushButton
}

func NewTodoApp() *TodoApp {
	app := &TodoApp{
		QWidget: widgets.NewQWidget(nil, 0),
	}

	// Set up the layout
	layout := widgets.NewQVBoxLayout()

	// Create the input line
	app.inputLine = widgets.NewQLineEdit(nil)
	app.inputLine.SetPlaceholderText("Enter a new todo item")

	// Create the add button
	app.addButton = widgets.NewQPushButton2("Add Todo", nil)
	app.addButton.ConnectClicked(func(bool) {
		app.addTodo()
	})

	// Create the remove button
	app.removeButton = widgets.NewQPushButton2("Remove Todo", nil)
	app.removeButton.ConnectClicked(func(bool) {
		app.removeTodo()
	})

	// Create the save button
	app.saveButton = widgets.NewQPushButton2("Save List", nil)
	app.saveButton.ConnectClicked(func(bool) {
		app.saveList()
	})

	// Create the todo list
	app.todoList = widgets.NewQListWidget(nil)

	// Add widgets to the layout
	layout.AddWidget(app.inputLine, 0, 0)
	layout.AddWidget(app.addButton, 0, 0)
	layout.AddWidget(app.removeButton, 0, 0)
	layout.AddWidget(app.saveButton, 0, 0)
	layout.AddWidget(app.todoList, 0, 0)

	app.SetLayout(layout)
	app.SetWindowTitle("Todo List")
	app.Resize2(400, 300)

	return app
}

func (app *TodoApp) addTodo() {
	todoText := app.inputLine.Text()
	if todoText != "" {
		item := widgets.NewQListWidgetItem(nil)
		item.SetText(todoText)
		app.todoList.AddItem(item)
		app.inputLine.Clear()
	} else {
		widgets.QMessageBox_Information(nil, "Input Error", "Please enter a todo item.", widgets.QMessageBox__Ok, widgets.QMessageBox__Ok)
	}
}

func (app *TodoApp) removeTodo() {
	selectedItem := app.todoList.CurrentRow()
	if selectedItem != -1 {
		app.todoList.RemoveItem(app.todoList.Item(selectedItem))
	} else {
		widgets.QMessageBox_Information(nil, "Error", "Please select an item to remove.", widgets.QMessageBox__Ok, widgets.QMessageBox__Ok)
	}
}

func (app *TodoApp) saveList() {
	fileName := "todo_list.txt"
	todoItems := app.todoList.Items()
	file, err := os.Create(fileName)
	if err != nil {
		fmt.Println(err)
		return
	}
	defer file.Close()

	for _, item := range todoItems {
		file.WriteString(item.Text() + "\n")
	}

	widgets.QMessageBox_Information(nil, "Success", "Todo list saved to "+fileName+".", widgets.QMessageBox__Ok, widgets.QMessageBox__Ok)
}

func main() {
	gui.NewQApplication(len(os.Args), os.Args)

	todoApp := NewTodoApp()
	todoApp.Show()

	gui.QApplication_Exec()
}
```

### Explanation

1. **Imports**: We import the necessary packages from the `Goi` library.
2. **TodoApp Struct**: This struct holds the main components of the application, including the todo list, input line, add button, remove button, and save button.
3. **NewTodoApp Function**: This function initializes the GUI components, sets up the layout, and connects the button click events to the `addTodo`, `removeTodo`, and `saveList` methods.
4. **addTodo Method**: This method retrieves the text from the input line, adds it to the todo list if it's not empty, and clears the input line. If the input is empty, it shows a message box.
5. **removeTodo Method**: This method removes the selected item from the todo list.
6. **saveList Method**: This method saves the todo list items to a file named `todo_list.txt`.
7. **main Function**: This is the entry point of the application. It initializes the application and shows the main window.

### Running the Application

1. Save the code in a file named `main.go`.
2. Open a terminal and navigate to the directory where `main.go` is located.
3. Run the application using:
   ```bash
   go run main.go
   ```

This enhanced todo list application includes features like removing items, saving the list to a file, and marking items as completed.

### Conclusion

This example demonstrates how to create an enhanced todo list application with additional features using the `Goi` UI library in Golang. You can further customize this application by adding more features or improving existing ones.

